mapper.select:
SELECT s.*
FROM public.nocode_work_submission s JOIN public.nocode_work_draft d
ON d.id = s.draft_id
WHERE s.id = #{id}
AND s.creator = #{actor}
AND d.creator = #{actor}
AND d.source_type = #{source}
AND d.source_id = #{taskId}
AND s.deleted = 0
AND d.deleted = 0

SELECT *
FROM public.nocode_work_submission
WHERE draft_id = #{draftId}
AND creator = #{actor}
AND deleted = 0

SELECT *
FROM public.nocode_work_submission
WHERE creator = #{actor}
AND idempotency_key = #{key}
AND deleted = 0

SELECT *
FROM public.nocode_work_submission
WHERE id = #{id}
AND creator = #{actor}
AND deleted = 0
